async function listMessages(env,user,admin=false){if(admin&&!isAdmin(user))return json({error:'관리자만 통합 접수함을 열 수 있습니다.'},403);const locations=admin?(await env.DB.prepare('SELECT reference, building, floor, room, bed FROM care_board_requests').all()).results:[];const statement=admin?env.DB.prepare('SELECT reference, hospital_name, recipient, category, title, body, contact, status, created_at FROM secure_messages ORDER BY created_at DESC LIMIT 100'):env.DB.prepare('SELECT reference, hospital_name, recipient, category, title, body, contact, status, created_at FROM secure_messages WHERE sender_user_id = ? ORDER BY created_at DESC LIMIT 50').bind(user.id);const result=await statement.all();return json({admin,items:(result.results||[]).map(x=>({reference:x.reference,location:admin?locations.find(b=>b.reference===x.reference):undefined,hospitalName:x.hospital_name,recipientLabel:recipientLabels[x.recipient]||x.recipient,category:x.title.startsWith('환자·보호자 의뢰 · ')?'환자·보호자 의뢰':x.title.startsWith('간병인 신청 · ')?'간병인 신청':x.category,title:x.title,body:x.body,contact:x.contact,status:x.status,createdAt:new Date(x.created_at).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})}))})}
async function listBoard(request,env){const hospitalId=clean(new URL(request.url).searchParams.get('hospitalId'),80);if(!hospitalId)return json({error:'병원을 선택해 주세요.'},400);const rows=await env.DB.prepare('SELECT b.reference, b.building, b.floor, b.room, b.bed, b.start_date, b.start_time, b.end_date, b.end_time FROM care_board_requests b JOIN secure_messages m ON m.id = b.message_id WHERE b.hospital_id = ? AND m.status = ? ORDER BY b.start_date, b.start_time LIMIT 500').bind(hospitalId,'접수').all();return json({items:(rows.results||[]).map(b=>({reference:b.reference,building:b.building,floor:b.floor,room:b.room,bed:b.bed,date:b.start_date,time:b.start_time,endDate:b.end_date,endTime:b.end_time}))})}
function asset(pathname){if(pathname in TEXT_ASSETS){const types={'.html':'text/html; charset=utf-8','.css':'text/css; charset=utf-8','.js':'text/javascript; charset=utf-8','.webmanifest':'application/manifest+json; charset=utf-8'};const ext=pathname==='/'?'.html':pathname.slice(pathname.lastIndexOf('.'));return new Response(TEXT_ASSETS[pathname],{headers:{...securityHeaders,'Content-Type':types[ext]||'text/plain; charset=utf-8','Cache-Control':pathname==='/'||pathname.endsWith('.html')?'no-cache':'public, max-age=300'}})}if(pathname in BINARY_ASSETS){const raw=atob(BINARY_ASSETS[pathname]);const bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));const type=pathname.endsWith('.svg')?'image/svg+xml':pathname.endsWith('.png')?'image/png':pathname.endsWith('.webp')?'image/webp':'application/octet-stream';return new Response(bytes,{headers:{...securityHeaders,'Content-Type':type,'Cache-Control':'public, max-age=86400'}})}return null}
export default{async fetch(request,env){try{const url=new URL(request.url);if(url.pathname.startsWith('/api/admin-auth/'))return adminAuth(request,env,url.pathname.slice('/api/admin-auth/'.length));if(url.pathname==='/api/room-edit'){const user=await resolveUser(request,env);if(!user)return json({error:'로그인이 필요합니다.'},401);if(!isAdmin(user))return json({error:'관리자만 수정할 수 있습니다.'},403);if(request.method!=='POST')return json({error:'허용되지 않은 요청입니다.'},405);return editRoom(request,env,user)}if(url.pathname==='/api/session'){if(request.method!=='GET')return json({error:'허용되지 않은 요청입니다.'},405);const user=await resolveUser(request,env);return json({authenticated:!!user,admin:isAdmin(user)})}if(url.pathname==='/api/my-messages'){const user=await resolveUser(request,env);if(!user)return json({error:'로그인 후 확인할 수 있습니다.'},401);if(request.method!=='GET')return json({error:'허용되지 않은 요청입니다.'},405);return listMessages(env,user,false)}if(url.pathname==='/api/board'){if(request.method!=='GET')return json({error:'허용되지 않은 요청입니다.'},405);return listBoard(request,env)}if(url.pathname==='/api/messages'){const user=await resolveUser(request,env);if(!user)return json({error:'로그인 후 접수할 수 있습니다.'},401);if(request.method==='POST')return createMessage(request,env,user);if(request.method==='GET')return listMessages(env,user,true);return json({error:'허용되지 않은 요청입니다.'},405)}if(request.method!=='GET'&&request.method!=='HEAD')return new Response('Method Not Allowed',{status:405,headers:securityHeaders});return asset(url.pathname)||new Response('Not Found',{status:404,headers:securityHeaders})}catch(error){console.error('secure-message-error',error);return json({error:'보안 저장 서비스에 일시적인 문제가 있습니다.'},500)}}};

function validSchedule(s){if(!s)return false;const date=v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&Number.isFinite(Date.parse(v+'T00:00:00Z'))&&new Date(v+'T00:00:00Z').toISOString().slice(0,10)===v;const time=v=>typeof v==='string'&&/^([01]\d|2[0-3]):[0-5]\d$/.test(v);return date(s.date)&&date(s.endDate)&&time(s.time)&&time(s.endTime)&&s.endDate+'T'+s.endTime>s.date+'T'+s.time}
async function editRoom(request,env,user){
 if(!sameOrigin(request))return json({error:'허용되지 않은 요청입니다.'},403);
 let data;try{const raw=await request.text();if(raw.length>3000)return json({error:'입력이 너무 깁니다.'},413);data=JSON.parse(raw)}catch{return json({error:'입력을 확인해 주세요.'},400)}
 const fields={building:40,floor:20,room:30,bed:20},loc={};
 for(const [key,max] of Object.entries(fields)){const v=data.location?.[key];if(typeof v!=='string'||v.length>max||/[\r\n]/.test(v))return json({error:'병실 정보를 확인해 주세요.'},400);loc[key]=v.trim()}
 if(!loc.building||!loc.room||!/^\d{1,2}층$/.test(loc.floor))return json({error:'건물·층·병실을 입력해 주세요.'},400);
 const old=await env.DB.prepare('SELECT b.*, m.body FROM care_board_requests b JOIN secure_messages m ON m.id=b.message_id WHERE b.reference=?').bind(clean(data.reference,80)).first();
 if(!old)return json({error:'수정할 의뢰를 찾을 수 없습니다.'},404);
 if(Object.keys(fields).some(k=>data.expected?.[k]!==old[k]))return json({error:'다른 변경이 있습니다. 접수함을 새로고침하고 다시 수정해 주세요.'},409);
 let body=old.body;for(const [key,label] of Object.entries({building:'건물',floor:'층',room:'병실',bed:'침상'})){const re=new RegExp('^'+label+':[^\\n]*','m');body=re.test(body)?body.replace(re,()=>label+': '+loc[key]):body+'\n'+label+': '+loc[key]}
 for(const [key,label,max] of [['assignedName','담당 간병인 · 자격',80],['assignedPhone','담당 간병인 연락처',30]]){const value=data.location?.[key];if(value!==undefined){if(typeof value!=='string'||value.length>max||/[\r\n]/.test(value))return json({error:'담당 간병인 정보를 확인해 주세요.'},400);const re=new RegExp('^'+label+':[^\\n]*','m');body=re.test(body)?body.replace(re,()=>label+': '+value.trim()):body+'\n'+label+': '+value.trim()}}
 let movement=null;const move=data.location;if(move.movedDate||move.movedTime||move.previousRoom){if(!/^\d{4}-\d{2}-\d{2}$/.test(move.movedDate||'')||!Number.isFinite(Date.parse(move.movedDate+'T00:00:00Z'))||new Date(move.movedDate+'T00:00:00Z').toISOString().slice(0,10)!==move.movedDate||!/^([01]\d|2[0-3]):[0-5]\d$/.test(move.movedTime||'')||typeof move.previousRoom!=='string'||!move.previousRoom.trim()||move.previousRoom.length>80||/[\r\n]/.test(move.previousRoom))return json({error:'移動'.replace('移動','이동')+' 날짜·시간·이전 병실을 올바르게 입력해 주세요.'},400);movement={date:move.movedDate,time:move.movedTime,from:move.previousRoom.trim(),to:loc.room};body+='\n병실 이동 기록: '+movement.date+' '+movement.time+' (한국 시간) · '+movement.from+' → '+movement.to+' · 침상 '+(loc.bed||'미지정')}
 const changed=await env.DB.batch([
 env.DB.prepare('UPDATE care_board_requests SET building=?, floor=?, room=?, bed=? WHERE reference=? AND building=? AND floor=? AND room=? AND bed=?').bind(loc.building,loc.floor,loc.room,loc.bed,old.reference,old.building,old.floor,old.room,old.bed),
 env.DB.prepare('UPDATE secure_messages SET body=? WHERE id=? AND changes()=1').bind(body,old.message_id),
 env.DB.prepare('INSERT INTO secure_message_audit (message_id,actor_user_id,action,created_at) SELECT ?,?,?,? WHERE changes()=1').bind(old.message_id,user.id,JSON.stringify({action:'room_updated',before:Object.fromEntries(Object.keys(fields).map(k=>[k,old[k]])),after:loc,staffUpdated:data.location?.assignedName!==undefined,movement}),new Date().toISOString())]);
 if((changed[0]?.meta?.changes??changed[0]?.changes)===0)return json({error:'다른 변경이 있습니다. 새로고침 후 다시 수정해 주세요.'},409);
 return json({location:loc,body});
}

// Private Worker code: never included in browser assets.
const ADMIN_COOKIE='__Host-care24_admin';
const bytesHex=bytes=>Array.from(new Uint8Array(bytes),b=>b.toString(16).padStart(2,'0')).join('');
const randomHex=size=>bytesHex(crypto.getRandomValues(new Uint8Array(size)));
const digest=async value=>bytesHex(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value)));
function sessionToken(request){return (request.headers.get('Cookie')||'').split(';').map(x=>x.trim()).find(x=>x.startsWith(ADMIN_COOKIE+'='))?.slice(ADMIN_COOKIE.length+1)||''}
async function passwordHash(password,salt){const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);return bytesHex(await crypto.subtle.deriveBits({name:'PBKDF2',hash:'SHA-512',salt:new TextEncoder().encode(salt),iterations:100000},key,512))}
function sameHash(a,b){let difference=a.length^b.length;for(let i=0;i<Math.max(a.length,b.length);i++)difference|=(a.charCodeAt(i)||0)^(b.charCodeAt(i)||0);return difference===0}
async function resolveUser(request,env){
 const token=sessionToken(request);
 if(/^[a-f0-9]{64}$/.test(token)){const session=await env.DB.prepare('SELECT token_hash FROM admin_sessions WHERE token_hash=? AND expires_at>?').bind(await digest(token),Date.now()).first();if(session)return {id:'care24-password-admin',email:'',admin:true}}
 return userFrom(request);
}
function withAdminCookie(response,token){response.headers.set('Set-Cookie',ADMIN_COOKIE+'='+token+'; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age='+(token?28800:0));return response}
async function startAdminSession(env){const token=randomHex(32);await env.DB.batch([env.DB.prepare('DELETE FROM admin_sessions WHERE expires_at<=?').bind(Date.now()),env.DB.prepare('INSERT INTO admin_sessions(token_hash,expires_at) VALUES(?,?)').bind(await digest(token),Date.now()+28800000)]);return withAdminCookie(json({ok:true,admin:true}),token)}
async function adminAuth(request,env,path){
 if(path==='state'){
  if(request.method!=='GET')return json({error:'허용되지 않은 요청입니다.'},405);
  const exists=await env.DB.prepare('SELECT id FROM admin_accounts WHERE id=1').first();
  const user=await resolveUser(request,env);
  return json({configured:!!exists,setupAllowed:!exists&&isPlatformAdmin(userFrom(request)),admin:isAdmin(user)});
 }
 if(!['login','setup','logout'].includes(path))return json({error:'찾을 수 없습니다.'},404);
 if(request.method!=='POST')return json({error:'허용되지 않은 요청입니다.'},405);
 if(request.headers.get('Origin')!==new URL(request.url).origin||!request.headers.get('Content-Type')?.startsWith('application/json'))return json({error:'허용되지 않은 전송 요청입니다.'},403);
 if(path==='logout'){const token=sessionToken(request);if(token)await env.DB.prepare('DELETE FROM admin_sessions WHERE token_hash=?').bind(await digest(token)).run();return withAdminCookie(json({ok:true}),'')}
 let data;try{const raw=await request.text();if(raw.length>2048)return json({error:'입력이 너무 깁니다.'},400);data=JSON.parse(raw)}catch{return json({error:'입력을 확인해 주세요.'},400)}
 if(!data||typeof data.username!=='string'||typeof data.password!=='string'||data.password.length>128)return json({error:'아이디와 비밀번호를 확인해 주세요.'},400);
 const username=data.username.trim().toLowerCase(),password=data.password;
 if(path==='setup'){
  if(!isPlatformAdmin(userFrom(request)))return json({error:'최초 계정 설정은 사이트 소유자만 할 수 있습니다.'},403);
  if(!/^[a-z0-9_.-]{3,40}$/.test(username)||password.length<12)return json({error:'아이디는 영문·숫자 등 3~40자, 비밀번호는 12자 이상으로 입력해 주세요.'},400);
  if(await env.DB.prepare('SELECT id FROM admin_accounts WHERE id=1').first())return json({error:'관리자 계정이 이미 설정되어 있습니다.'},409);
  const salt=randomHex(32),hash=await passwordHash(password,salt);
  const result=await env.DB.prepare('INSERT OR IGNORE INTO admin_accounts(id,username,password_hash,salt,created_at) VALUES(1,?,?,?,?)').bind(username,hash,salt,new Date().toISOString()).run();
  if((result.meta?.changes??result.changes)!==1)return json({error:'관리자 계정이 이미 설정되어 있습니다.'},409);
  return startAdminSession(env);
 }
 const client=await digest(request.headers.get('CF-Connecting-IP')||'unknown-client'),now=Date.now();
 await env.DB.prepare('DELETE FROM admin_login_attempts WHERE attempted_at<?').bind(now-900000).run();
 const rate=await env.DB.prepare('SELECT COUNT(*) AS count FROM admin_login_attempts WHERE client_key=? AND attempted_at>=?').bind(client,now-900000).first();
 if(Number(rate?.count)>=8)return json({error:'로그인 시도가 많습니다. 15분 후 다시 시도해 주세요.'},429);
 await env.DB.prepare('INSERT INTO admin_login_attempts(client_key,attempted_at) VALUES(?,?)').bind(client,now).run();
 const account=await env.DB.prepare('SELECT username,password_hash,salt FROM admin_accounts WHERE id=1').first();
 const candidate=await passwordHash(password,account?.salt||'0'.repeat(64));
 if(!account||account.username!==username||!sameHash(candidate,account.password_hash))return json({error:'아이디 또는 비밀번호가 올바르지 않습니다.'},401);
 await env.DB.prepare('DELETE FROM admin_login_attempts WHERE client_key=?').bind(client).run();
 return startAdminSession(env);
}
